import { join } from 'node:path';
import { createRequire } from 'node:module';
import * as source from '/Users/aantich/dev/oneringai/src/index.ts';
import * as publicESM from '/Users/aantich/dev/oneringai/dist/index.js';
const publicCJS = createRequire(import.meta.url)('/Users/aantich/dev/oneringai/dist/index.cjs');
const reports=[];
const scope={ownerId:'review-owner',namespace:'task-review'};
const note=(id:string,text='Cap 50',extra={})=>({id,category:'constraint' as const,text,source:{label:'Host'},...extra});
function errorText(fn:()=>unknown){try{fn();return null;}catch(error){return error instanceof Error?error.message:String(error);}}
for(const [variant,lib] of [['source',source],['public-esm',publicESM],['public-cjs',publicCJS]] as const){
  // Every admitted state should be accepted by the plugin's own restoration validator.
  const p=new lib.TaskStatePluginNextGen({scope,taskId:'task'});
  try{p.updateHost({notes:[note('old')]},0);p.updateHost({notes:[note('new','Cap40',{supersedes:'old'})]},1);p.pruneResolved(['old'],[],2);p.updateHost({notes:[note('old','Independent new constraint')]},3);const snapshot=p.getState();const validationError=errorText(()=>p.validateState(snapshot));const restoreError=errorText(()=>p.restoreState(snapshot));assert.equal(p.revision,4);assert.match(validationError!,/correction links/);reports.push({variant,case:'pruned-id-reuse',revision:p.revision,notes:snapshot.notes,validationError,restoreError});}finally{p.destroy();}
  const reference=new lib.TaskStatePluginNextGen({scope,taskId:'capacity'});reference.updateHost({notes:[note('active')]},0);const maxPromptTokens=lib.simpleTokenEstimator.estimateTokens(await reference.getContent());const maxSnapshotBytes=Buffer.byteLength(JSON.stringify(reference.getState()));reference.destroy();
  for(const [limit,value] of [['maxPromptTokens',maxPromptTokens],['maxSnapshotBytes',maxSnapshotBytes]] as const){const p=new lib.TaskStatePluginNextGen({scope,taskId:'capacity',[limit]:value});try{p.updateHost({notes:[note('active')]},0);const before=p.getState();const resolveError=errorText(()=>p.updateHost({resolve:['active']},1));const pruneError=errorText(()=>p.pruneResolved(['active'],[],1));assert.ok(resolveError);assert.match(pruneError!,/active note/);assert.deepEqual(p.getState(),before);reports.push({variant,case:'capacity-recovery',limit,value,resolveError,pruneError,revision:p.revision,activeRecords:p.getState().notes.length});}finally{p.destroy();}}
  // The same recovery deadlock occurs at the unmodified default 8000-token cap.
  const many=Array.from({length:14},(_,i)=>note(`default-${i}`,'x'.repeat(2000)));
  const measure=new lib.TaskStatePluginNextGen({scope,taskId:'default-capacity',maxPromptTokens:20000});
  measure.updateHost({notes:many},0);const fullContent=await measure.getContent();const fullTokens=lib.simpleTokenEstimator.estimateTokens(fullContent);measure.destroy();
  const baseLast=2000-Math.floor((fullTokens-8000)*3.5);let admittedDefault=false;
  for(let adjust=-5;adjust<=5;adjust++){
    const length=baseLast+adjust;if(length<1||length>2000)continue;many[13]!.text='x'.repeat(length);
    const candidate=new lib.TaskStatePluginNextGen({scope,taskId:'default-capacity'});
    try{candidate.updateHost({notes:many},0);const tokens=lib.simpleTokenEstimator.estimateTokens(await candidate.getContent());if(tokens!==8000)continue;
      const resolveError=errorText(()=>candidate.updateHost({resolve:['default-0']},1));const pruneError=errorText(()=>candidate.pruneResolved(['default-0'],[],1));assert.ok(resolveError);assert.ok(pruneError);reports.push({variant,case:'default-capacity-recovery',maxPromptTokens:8000,actualTokens:tokens,activeRecords:many.length,resolveError,pruneError});admittedDefault=true;break;
    }catch(error){if(candidate.revision===1)throw error;}finally{candidate.destroy();}
  }
  assert.ok(admittedDefault,'Default-capacity boundary fixture must be admitted exactly');
  for(const mode of ['run','stream'] as const){
    const name=`review-budget-${variant}-${mode}`;let calls=0;let selected='';let updates=0;let eventCount=0;let phase='prepare';
    const provider={name:'synthetic',capabilities:{text:true,images:false,audio:false,videos:false},validateConfig:async()=>true,listModels:async()=>[],getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxOutputTokens:1024}),
      generate:async(options:any)=>{calls++;selected=JSON.stringify(options.input);return{id:'r',object:'response',model:options.model,created_at:1,status:'completed',output_text:'OK',output:[{type:'message',role:lib.MessageRole.ASSISTANT,content:[{type:lib.ContentType.OUTPUT_TEXT,text:'OK'}]}],usage:{input_tokens:1,output_tokens:1,total_tokens:2}};},
      async*streamGenerate(options:any){calls++;selected=JSON.stringify(options.input);yield{type:lib.StreamEventType.OUTPUT_TEXT_DELTA,response_id:'r',item_id:'i',output_index:0,content_index:0,sequence_number:0,delta:'OK'};yield{type:lib.StreamEventType.RESPONSE_COMPLETE,response_id:'r',status:'completed',usage:{input_tokens:1,output_tokens:1,total_tokens:2},iterations:1};}};
    lib.Connector.create({name,vendor:lib.Vendor.OpenAI,auth:{type:'none'},options:{provider}});
    const a=lib.Agent.create({connector:name,model:'gpt-4o-mini',userId:scope.ownerId,thinking:{enabled:false},emptyResponseRetry:{enabled:false},context:{model:'gpt-4o-mini',features:{workingMemory:false,inContextMemory:false,taskState:true},plugins:{taskState:{scope,taskId:'race'}}},hooks:{'before:llm':async(c:any)=>{phase='dispatch';c.options.instructions=(c.options.instructions??'')+' Host adds harmless instruction text to trigger final recount event.';return{};}}});
    try{const task=a.context.getPlugin('task_state')! as source.TaskStatePluginNextGen;task.updateHost({notes:[note('old','CAP50')]},0);a.context.on('budget:updated',()=>{eventCount++;if(phase==='dispatch'&&updates++===0)task.updateHost({notes:[note('corrected','CAP40',{supersedes:'old'})]},task.revision);});if(mode==='run')await a.run('Continue');else for await(const _ of a.stream('Continue')){/*drain*/}const state=task.getState();assert.equal(calls,1);assert.equal(state.revision,2);assert.ok(selected.includes('CAP50'));assert.ok(!selected.includes('CAP40'));reports.push({variant,case:'budget-listener-stale-dispatch',mode,calls,eventCount,revision:state.revision,providerHadOldConstraint:selected.includes('CAP50'),providerHadCorrection:selected.includes('CAP40'),activeConstraint:state.notes.find(n=>n.id==='corrected')?.text});}finally{a.destroy();lib.Connector.remove(name);}
  }
}
await writeFile('/tmp/oneringai-stage04-review-reproductions.json',JSON.stringify(reports,null,2)+'\n');console.log(JSON.stringify(reports,null,2));

