 const seed=new lib.TaskStatePluginNextGen({scope,taskId:'cap'});seed.updateHost({notes:[note('active')]},0);const tokens=lib.simpleTokenEstimator.estimateTokens(await seed.getContent());const bytes=Buffer.byteLength(JSON.stringify(seed.getState()));seed.destroy();
 for(const[limit,value]of[['maxPromptTokens',tokens+16],['maxSnapshotBytes',bytes+100]]as const){const p=new lib.TaskStatePluginNextGen({scope,taskId:'cap',[limit]:value});try{p.updateHost({notes:[note('active')]},0);p.updateHost({resolve:['active']},1);p.pruneResolved(['active'],[],2);assert.equal(p.getState().notes.length,0);reports.push({variant,case:'capacity-headroom-control',limit,value,passed:true});}finally{p.destroy();}}
}
let modelCalls=0;const name='stage04-review-amos';publicESM.Connector.create({name,vendor:publicESM.Vendor.OpenAI,auth:{type:'none'},options:{provider:{name:'synthetic',capabilities:{text:true,images:false,audio:false,videos:false},validateConfig:async()=>true,listModels:async()=>[],getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxOutputTokens:1024}),generate:async()=>{modelCalls++;throw Error('No model call expected');},async*streamGenerate(){modelCalls++;throw Error('No model call expected');}}}});
const config=structuredClone(DEFAULT_CONFIG);config.session.autoSave=false;config.taskState={enabled:true,taskId:'amos',ownerId:scope.ownerId,namespace:'amos-review'};const runner=new AgentRunner(config,[],join(directory,'amos'));const command=new ContextCommand();const app={getAgent:()=>runner};const invoke=(args:string[])=>command.execute({app,args,rawInput:'/context '+args.join(' ')} as any);
try{await runner.initialize(name,'gpt-4o-mini');for(let i=0;i<100;i++){const result=await invoke(['task','add',String(runner.getTaskState()!.revision),'constraint',`note-${i}`,`Confirmed constraint ${i}`]);assert.equal(result.success,true);}const resolve=await invoke(['task','resolve','100','note-0']);assert.equal(resolve.success,true);const add=await invoke(['task','add','101','constraint','new','New constraint']);const correct=await invoke(['task','correct','101','note-1','corrected','Corrected constraint']);const prune=await invoke(['task','prune','101','note-0']);assert.equal(add.success,false);assert.equal(correct.success,false);assert.equal(prune.success,false);const state=runner.getTaskState()!;reports.push({variant:'amos-actual-runner',case:'resolved-record-cap-no-recovery',recordCount:state.notes.length,revision:state.revision,resolved:state.notes[0]?.resolved,resolve,add,correct,prune,modelCalls});assert.equal(modelCalls,0);}finally{runner.destroy();publicESM.Connector.remove(name);}
}finally{await rm(directory,{recursive:true,force:true});}
